export function tailText(text, budget) {
    const bytes = Buffer.from(text, "utf8");
    if (!(budget >= 0) || !Number.isFinite(budget)) {
        return "";
    }
    const limit = Math.min(Math.floor(budget), bytes.length);
    if (limit === 0) {
        return "";
    }
    let start = bytes.length;
    let used = 0;
    while (true) {
        let cpStart = start - 1;
        if (cpStart < 0) {
            break;
        }
        while (cpStart > 0 && (bytes[cpStart] & 0xc0) === 0x80) {
            cpStart--;
        }
        const seqLen = start - cpStart;
        if (seqLen > limit - used) {
            break;
        }
        if (!isValidUtf8Sequence(bytes, cpStart, seqLen)) {
            break;
        }
        start = cpStart;
        used += seqLen;
        if (used === limit) {
            break;
        }
    }
    if (start >= bytes.length) {
        return "";
    }
    let suffix = bytes.subarray(start).toString("utf8");
    if (suffix.includes("\uFFFD")) {
        return "";
    }
    return suffix;
}

function isValidUtf8Sequence(bytes, offset, length) {
    const b0 = bytes[offset];
    if (length === 1) {
        return b0 < 0x80;
    }
    if (length === 2) {
        return (b0 & 0xe0) === 0xc0 && (bytes[offset + 1] & 0xc0) === 0x80 && (b0 & 0x1e) !== 0;
    }
    if (length === 3) {
        if (!((b0 & 0xf0) === 0xe0 && (bytes[offset + 1] & 0xc0) === 0x80 && (bytes[offset + 2] & 0xc0) === 0x80)) {
            return false;
        }
        if (b0 === 0xe0 && (bytes[offset + 1] & 0xe0) === 0x80) {
            return false;
        }
        if (b0 === 0xed && (bytes[offset + 1] & 0xe0) === 0xa0) {
            return false;
        }
        return true;
    }
    if (length === 4) {
        if (!((b0 & 0xf8) === 0xf0 && (bytes[offset + 1] & 0xc0) === 0x80 && (bytes[offset + 2] & 0xc0) === 0x80 && (bytes[offset + 3] & 0xc0) === 0x80)) {
            return false;
        }
        if (b0 === 0xf0 && (bytes[offset + 1] & 0xf0) === 0x80) {
            return false;
        }
        if (b0 === 0xf4 && (bytes[offset + 1] & 0xf0) !== 0) {
            return false;
        }
        return (b0 & 0x07) !== 0;
    }
    return false;
}

